#include <memory>

void const_test() {
    // p is const; the pointer p holds cannot change, but the value can.
    const std::auto_ptr<int> p(new int(42));
    const std::auto_ptr<int> q(new int(0));

    // OK: Modifying the value pointed to by p and q
    *q = *p; 
    *p = -77;

    // ERROR: Attempting to change the ownership/pointer held by p or q
    // q = p; // Compile-time error: assignment operator is not const-qualified
}
